import pandas as pd
import numpy as np
from datetime import datetime
import json
import matplotlib.pyplot as plt
import seaborn as sns
import base64
import io

def df_to_base64_img(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    encoded = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{encoded}"

def main():
    print("Loading data...")
    df = pd.read_csv('/app/benchmark/data.csv')
    df.columns = [col.replace('\ufeff', '') for col in df.columns]

    # Fill NA where needed
    df['Review_Theme'] = df['Review_Theme'].fillna('General')

    apps = df['App'].unique().tolist()

    print("Calculating KPIs...")
    # App Sentiment Comparison
    app_stats = df.groupby('App').agg({
        'Star_Rating': 'mean',
        'Sentiment_Polarity': 'mean',
        'Thumbs_Up_Count': 'mean'
    }).reset_index()

    # Thematic Complaint Analysis
    theme_counts = df.groupby(['App', 'Review_Theme']).size().unstack(fill_value=0)
    theme_pct = theme_counts.div(theme_counts.sum(axis=1), axis=0) * 100

    # Sentiment-Rating Divergence
    # Mismatch: Star >= 4 but Sentiment < -0.1 OR Star <= 2 but Sentiment > 0.1
    df['Mismatch'] = ((df['Star_Rating'] >= 4) & (df['Sentiment_Polarity'] < -0.1)) | \
                     ((df['Star_Rating'] <= 2) & (df['Sentiment_Polarity'] > 0.1))
    mismatch_rate = df.groupby('App')['Mismatch'].mean() * 100

    print("Generating charts...")
    sns.set_theme(style="whitegrid")

    # Chart 1: Star Rating vs Sentiment Polarity by App
    fig, ax = plt.subplots(figsize=(8, 5))
    sns.scatterplot(data=app_stats, x='Star_Rating', y='Sentiment_Polarity', hue='App', s=200, ax=ax)
    for i in range(app_stats.shape[0]):
        ax.text(app_stats.Star_Rating[i], app_stats.Sentiment_Polarity[i]+0.01, app_stats.App[i], horizontalalignment='center')
    ax.set_title("Average Star Rating vs. Sentiment Polarity", fontweight='bold')
    ax.set_xlabel("Average Star Rating")
    ax.set_ylabel("Average Sentiment Polarity")
    chart1_base64 = df_to_base64_img(fig)

    # Chart 2: Theme Breakdown by App
    fig, ax = plt.subplots(figsize=(10, 6))
    theme_pct.plot(kind='bar', stacked=True, ax=ax, colormap='viridis')
    ax.set_title("Thematic Complaint Distribution by App (%)", fontweight='bold')
    ax.set_ylabel("Percentage of Reviews")
    ax.set_xlabel("")
    plt.xticks(rotation=0)
    plt.legend(title='Review Theme', bbox_to_anchor=(1.05, 1), loc='upper left')
    chart2_base64 = df_to_base64_img(fig)

    # Chart 3: Mismatch Rate by App
    fig, ax = plt.subplots(figsize=(8, 4))
    sns.barplot(x=mismatch_rate.index, y=mismatch_rate.values, ax=ax, palette='mako')
    ax.set_title("Sentiment-Rating Mismatch Rate (%)", fontweight='bold')
    ax.set_ylabel("Mismatch Rate (%)")
    ax.set_xlabel("")
    for i, v in enumerate(mismatch_rate.values):
        ax.text(i, v + 0.2, f"{v:.1f}%", ha='center')
    chart3_base64 = df_to_base64_img(fig)

    # Chart 4: Review Depth vs Sentiment
    fig, ax = plt.subplots(figsize=(8, 5))
    sns.histplot(data=df, x='Word_Count', hue='Star_Rating', bins=30, multiple='stack', palette='coolwarm')
